mod solution;

fn main() {
    let cases = [
    (r#"1->4->3->2->5->2"#, r#"1,2,2,4,3,5"#),
    (r#"4->1"#, r#"1,4"#),
    (r#"
4->1
"#, r#"1,4"#),
    (r#"  
1->4->3->2->5->2
  "#, r#"1,2,2,4,3,5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS partition-list");
}
